import{_ as i,o as l,a as e,a6 as t}from"./chunks/framework.BNef1kRO.js";const b=JSON.parse('{"title":"Figma AI UI Kit 组件库","description":"","frontmatter":{"title":"Figma AI UI Kit 组件库","pageClass":"page-resource-detail","status":"draft","search":false,"layout":"page"},"headers":[],"relativePath":"resources/uikit.md","filePath":"resources/uikit.md"}'),r={name:"resources/uikit.md"};function o(d,a,h,n,s,c){return l(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="figma-ai-ui-kit-赛博风格组件库" tabindex="-1">Figma AI UI Kit - 赛博风格组件库 <a class="header-anchor" href="#figma-ai-ui-kit-赛博风格组件库" aria-label="Permalink to &quot;Figma AI UI Kit - 赛博风格组件库&quot;">​</a></h1><h2 id="组件库介绍" tabindex="-1">组件库介绍 <a class="header-anchor" href="#组件库介绍" aria-label="Permalink to &quot;组件库介绍&quot;">​</a></h2><p>专为现代 Web/App 设计的赛博朋克风格 UI 组件库，包含 200+ 精美组件。</p><h3 id="核心特性" tabindex="-1">核心特性 <a class="header-anchor" href="#核心特性" aria-label="Permalink to &quot;核心特性&quot;">​</a></h3><ul><li>🎨 完整的设计系统</li><li>🔧 Auto Layout 自动布局</li><li>🌈 深色/浅色双主题</li><li>⚡ 组件变体功能</li><li>📱 响应式网格系统</li></ul><h2 id="组件清单" tabindex="-1">组件清单 <a class="header-anchor" href="#组件清单" aria-label="Permalink to &quot;组件清单&quot;">​</a></h2><h3 id="基础组件-40" tabindex="-1">基础组件 (40+) <a class="header-anchor" href="#基础组件-40" aria-label="Permalink to &quot;基础组件 (40+)&quot;">​</a></h3><ul><li>Buttons - 按钮 (10种样式)</li><li>Inputs - 输入框 (表单控件)</li><li>Cards - 卡片 (数据展示)</li><li>Navigation - 导航栏</li><li>Typography - 排版系统</li></ul><h3 id="高级组件-80" tabindex="-1">高级组件 (80+) <a class="header-anchor" href="#高级组件-80" aria-label="Permalink to &quot;高级组件 (80+)&quot;">​</a></h3><ul><li>Dashboard - 仪表盘模块</li><li>Charts - 数据图表</li><li>Tables - 表格组件</li><li>Modals - 弹窗对话框</li><li>Forms - 表单页面</li></ul><h3 id="页面模板-20" tabindex="-1">页面模板 (20+) <a class="header-anchor" href="#页面模板-20" aria-label="Permalink to &quot;页面模板 (20+)&quot;">​</a></h3><ul><li>Landing Page - 落地页</li><li>Dashboard - 后台管理</li><li>Profile - 用户中心</li><li>Settings - 设置页面</li><li>Pricing - 价格页面</li></ul><h3 id="图标库-60" tabindex="-1">图标库 (60+) <a class="header-anchor" href="#图标库-60" aria-label="Permalink to &quot;图标库 (60+)&quot;">​</a></h3><ul><li>赛博朋克风格图标集</li><li>支持多种尺寸</li><li>可自定义颜色</li></ul><h2 id="下载说明" tabindex="-1">下载说明 <a class="header-anchor" href="#下载说明" aria-label="Permalink to &quot;下载说明&quot;">​</a></h2><p><strong>Figma 社区文件</strong>：<a href="https://figma.com/@liuli-design" target="_blank" rel="noreferrer">在线使用</a></p><p><strong>本地副本：</strong> 文件与授权仍在核实，暂不提供下载。</p><h2 id="使用教程" tabindex="-1">使用教程 <a class="header-anchor" href="#使用教程" aria-label="Permalink to &quot;使用教程&quot;">​</a></h2><h3 id="第一步-复制到你的文件" tabindex="-1">第一步：复制到你的文件 <a class="header-anchor" href="#第一步-复制到你的文件" aria-label="Permalink to &quot;第一步：复制到你的文件&quot;">​</a></h3><ol><li>打开 Figma 社区链接</li><li>点击&quot;Duplicate&quot;复制到你的账户</li><li>文件会出现在你的 Drafts 中</li></ol><h3 id="第二步-启用组件库" tabindex="-1">第二步：启用组件库 <a class="header-anchor" href="#第二步-启用组件库" aria-label="Permalink to &quot;第二步：启用组件库&quot;">​</a></h3><ol><li>打开你的设计文件</li><li>点击 Assets 面板</li><li>点击书籍图标 → Enable library</li><li>选择 &quot;AI UI Kit&quot;</li></ol><h3 id="第三步-使用组件" tabindex="-1">第三步：使用组件 <a class="header-anchor" href="#第三步-使用组件" aria-label="Permalink to &quot;第三步：使用组件&quot;">​</a></h3><ol><li>在 Assets 面板搜索组件</li><li>拖拽到画布即可使用</li><li>在右侧面板修改组件属性</li></ol><h2 id="设计规范" tabindex="-1">设计规范 <a class="header-anchor" href="#设计规范" aria-label="Permalink to &quot;设计规范&quot;">​</a></h2><h3 id="颜色系统" tabindex="-1">颜色系统 <a class="header-anchor" href="#颜色系统" aria-label="Permalink to &quot;颜色系统&quot;">​</a></h3><table tabindex="0"><thead><tr><th>颜色</th><th>用途</th><th>Light / Dark</th></tr></thead><tbody><tr><td>Primary</td><td>主要按钮、链接</td><td><code>#FF8B2F</code> / <code>#56B7FF</code></td></tr><tr><td>Secondary</td><td>次要元素</td><td><code>#315DFF</code> / <code>#8B5CF6</code></td></tr><tr><td>Accent</td><td>强调内容</td><td><code>#7A3CFF</code> / <code>#FF8B2F</code></td></tr><tr><td>Background</td><td>背景色</td><td><code>#F7F3EA</code> / <code>#070A12</code></td></tr><tr><td>Surface</td><td>卡片背景</td><td><code>#FFFAF1</code> / <code>#0B1020</code></td></tr></tbody></table><h3 id="字体系统" tabindex="-1">字体系统 <a class="header-anchor" href="#字体系统" aria-label="Permalink to &quot;字体系统&quot;">​</a></h3><ul><li><strong>标题</strong>：Inter (700-900)</li><li><strong>正文</strong>：Inter (400-600)</li><li><strong>等宽</strong>：JetBrains Mono</li></ul><h3 id="间距系统" tabindex="-1">间距系统 <a class="header-anchor" href="#间距系统" aria-label="Permalink to &quot;间距系统&quot;">​</a></h3><p>基于 8px 网格：4, 8, 12, 16, 24, 32, 48, 64</p><h2 id="自定义指南" tabindex="-1">自定义指南 <a class="header-anchor" href="#自定义指南" aria-label="Permalink to &quot;自定义指南&quot;">​</a></h2><h3 id="修改主题色" tabindex="-1">修改主题色 <a class="header-anchor" href="#修改主题色" aria-label="Permalink to &quot;修改主题色&quot;">​</a></h3><ol><li>进入 <code>🎨 Styles</code> 页面</li><li>选择 Color Styles</li><li>双击颜色并修改 Hex 值</li><li>所有组件自动更新</li></ol><h3 id="创建新组件" tabindex="-1">创建新组件 <a class="header-anchor" href="#创建新组件" aria-label="Permalink to &quot;创建新组件&quot;">​</a></h3><ol><li>参考现有组件结构</li><li>使用 Auto Layout 布局</li><li>创建组件变体</li><li>添加到组件库</li></ol><h2 id="应用案例" tabindex="-1">应用案例 <a class="header-anchor" href="#应用案例" aria-label="Permalink to &quot;应用案例&quot;">​</a></h2><ul><li>✅ SaaS 产品后台</li><li>✅ 数据可视化平台</li><li>✅ AI 工具界面</li><li>✅ Web3 DApp</li></ul><h2 id="技术支持" tabindex="-1">技术支持 <a class="header-anchor" href="#技术支持" aria-label="Permalink to &quot;技术支持&quot;">​</a></h2><p>遇到问题？</p><ul><li>使用文档将在文件与授权核实后补充。</li><li>💬 加入 Discord 社区</li><li>邮件联系：1442855983@qq.com</li></ul><hr><p><a href="/resources/">← 返回创作资源</a></p>',43)])])}const q=i(r,[["render",o]]);export{b as __pageData,q as default};
